#include <bits/stdc++.h>
using namespace std;

constexpr int LIMIT = 2000;
constexpr int WIDTH = LIMIT + 1;

int n;
vector<long long> x, y, r;
static unsigned char vis[WIDTH][WIDTH];

int getSigns(int i, int j) {
    int signs = 0;

    for (int k = 0; k < n; ++k) {
        long long dx = x[k] - i;
        long long dy = y[k] - j;
        long long q = dx * dx + dy * dy - r[k] * r[k];

        if (q == 0) return -1;
        if (q > 0) signs |= (1 << k);
    }

    return signs;
}

void floodFill(int si, int sj, int signs) {
    vector<int> st;
    st.push_back(si * WIDTH + sj);
    vis[si][sj] = true;

    while (!st.empty()) {
        int id = st.back();
        st.pop_back();

        int i = id / WIDTH;
        int j = id % WIDTH;

        auto add = [&](int ni, int nj) {
            if (ni < 0 || ni > LIMIT || nj < 0 || nj > LIMIT ||
                vis[ni][nj] || getSigns(ni, nj) != signs) {
                return;
            }

            vis[ni][nj] = true;
            st.push_back(ni * WIDTH + nj);
        };

        add(i + 1, j);
        add(i - 1, j);
        add(i, j + 1);
        add(i, j - 1);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    x.resize(n);
    y.resize(n);
    r.resize(n);

    for (int i = 0; i < n; ++i) {
        cin >> x[i] >> y[i] >> r[i];
        x[i] = (x[i] + 10) * 100;
        y[i] = (y[i] + 10) * 100;
        r[i] *= 100;
    }

    int ans = 0;

    for (int i = 0; i <= LIMIT; ++i) {
        for (int j = 0; j <= LIMIT; ++j) {
            if (vis[i][j]) continue;

            int signs = getSigns(i, j);
            if (signs == -1) continue;

            ++ans;
            floodFill(i, j, signs);
        }
    }

    cout << ans;
    return 0;
}

