#include <bits/stdc++.h>
using namespace std;

constexpr int LIMIT = 2000;
constexpr int WIDTH = LIMIT + 1;

int n, x[4], y[4], r[4];
bool vis[WIDTH][WIDTH];

int getCode(int i, int j) {
    int code = 0;
    for (int k = 0; k < n; ++k) {
        long long dx = x[k] - i;
        long long dy = y[k] - j;
        long long q = dx * dx + dy * dy - 1LL * r[k] * r[k];

        if (q == 0) return -1;
        code = code * 2 + (q > 0);
    }
    return code;
}

void floodFill(int si, int sj, int code) {
    queue<uint32_t> q;
    vis[si][sj] = true;
    q.push(static_cast<uint32_t>(si * WIDTH + sj));

    static const int di[] = {1, -1, 0, 0};
    static const int dj[] = {0, 0, 1, -1};

    while (!q.empty()) {
        uint32_t pos = q.front();
        q.pop();

        int i = pos / WIDTH;
        int j = pos % WIDTH;

        for (int d = 0; d < 4; ++d) {
            int ni = i + di[d];
            int nj = j + dj[d];

            if (ni < 0 || ni > LIMIT || nj < 0 || nj > LIMIT ||
                vis[ni][nj] || getCode(ni, nj) != code) {
                continue;
            }

            vis[ni][nj] = true;
            q.push(static_cast<uint32_t>(ni * WIDTH + nj));
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    for (int i = 0; i < n; ++i) {
        cin >> x[i] >> y[i] >> r[i];
        x[i] = (x[i] + 10) * 100;
        y[i] = (y[i] + 10) * 100;
        r[i] *= 100;
    }

    int ans = 0;

    for (int i = 0; i <= LIMIT; ++i) {
        for (int j = 0; j <= LIMIT; ++j) {
            if (vis[i][j]) continue;

            int code = getCode(i, j);
            if (code == -1) {
                vis[i][j] = true;
                continue;
            }

            ++ans;
            floodFill(i, j, code);
        }
    }

    cout << ans;
    return 0;
}

